We therefore define the $(1-1/e)$-regret of a sequence of
(possibly random) sets $\set{S_t}_{t=1}^T$ as
\vspace{-0.5em}
\[
\ensuremath{R}_{T} := \paren{1-1/e} \cdot \max_{S \subseteq V: |S| \le \ensuremath{k}}
\sum_{t=1}^T \ensuremath{f}_t(S) \ - \ \sum_{t=1}^T \E{\ensuremath{f}_t(S_t)} 
\]
where the expectation is taken over the distribution for each $S_t$.

We say an online algorithm producing a sequence of sets has 
\emph{no-$(1-1/e)$-regret} if $\limsup_{T \to \infty}
\frac{\ensuremath{R}_{T}}{T} \le 0$.

\Titleofalgo { Distributed Online Greedy (\algofont{DOG}\xspace) \ \ (described in the broadcast model) }
\KwIn { $\ensuremath{k} \in \ensuremath{\mathbb{N}}$, a set $V$, and $\alpha, \gamma, \eta
  \in \ensuremath{\mathbb{R}}_{>0}$.  Reasonable defaults are any $\alpha \in [1, \ln
    |V|]$, and $\gamma = \eta$ $=$ $\min\paren{1, \paren{|V|
      \ln |V|/g}^{1/2}}$, where $g$ is a guess for the maximum cumulative
reward of any single sensor~\cite{auer02}. }
Initialize $w_{\ensuremath{v}, i} \gets 1$ and $Z_{\ensuremath{v},i} \gets |V|$ for all
$\ensuremath{v} \in V$, $i \in [\ensuremath{k}]$.
Let  $\rho(x, y) := (1-\gamma)\frac{x}{y} +
\frac{\gamma}{|V|}$.\\
\For{ \KwEach \emph{round} $t = 1, 2, 3, \ldots $} {
  Initialize $S_{\ensuremath{v},t} \gets \emptyset$ for each $\ensuremath{v}$ in parallel.\\
  \For{ \KwEach \emph{stage} $i \in [\ensuremath{k}]$} {
    \For{ \KwEach \emph{sensor} $\ensuremath{v} \in V$ \emph{in parallel}} { 
      \Repeat {\emph{$\ensuremath{v}$ receives a message of type }
        $\tuple{\emph{select } \ensuremath{\operatorname{id}}}$ } {
         Sample $X_{\ensuremath{v}} \sim \Poisson{\alpha \cdot \rho(w_{\ensuremath{v},i}, Z_{\ensuremath{v},i})} $.\\
         \If{$(X_{\ensuremath{v}} \ge 1)$} { 
           Broadcast $\tuple{\text{sampled } X_{\ensuremath{v}}, \ensuremath{\operatorname{id}}(\ensuremath{v})}$; Receive messages from sensors $S$. (Include $\ensuremath{v} \in S$
           for convenience).\\
           \If{$\ensuremath{\operatorname{id}}(\ensuremath{v}) = \min_{\ensuremath{v}' \in S} \ensuremath{\operatorname{id}}(\ensuremath{v}')$}{
             Select exactly one element $v_{it}$ from $S$
             such that each $\ensuremath{v}'$ is selected with probability
             $X_{\ensuremath{v}'}/\sum_{u \in S} X_{u}$.\\              
             Broadcast $\tuple{\text{select } \ensuremath{\operatorname{id}}(\ensuremath{v}_{it})}$.\\
           }
           Receive message $\tuple{\text{select } \ensuremath{\operatorname{id}}(\ensuremath{v}_{it})}$.\\
           \If{$\ensuremath{\operatorname{id}}(\ensuremath{v}) = \ensuremath{\operatorname{id}}(\ensuremath{v}_{it})$}{
             Observe $\ensuremath{f}_t(S_{\ensuremath{v},t} + \ensuremath{v})$; $\ensuremath{\pi} \gets
             \ensuremath{f}_t(S_{\ensuremath{v},t} + \ensuremath{v}) -  \ensuremath{f}_t(S_{\ensuremath{v},t})$; $\Delta_{\ensuremath{v}} \gets  w_{\ensuremath{v},i} (\exp\set{\eta \cdot
               \ensuremath{\pi}/ \rho(w_{\ensuremath{v},i}, Z_{\ensuremath{v},i})} - 1)$;
             $Z_{\ensuremath{v},i} \gets Z_{\ensuremath{v},i} + \Delta_{\ensuremath{v}}$;
             $w_{\ensuremath{v}} \gets w_{\ensuremath{v}} + \Delta_{\ensuremath{v}}$;
             Broadcast $\tuple{\text{weight update }\Delta_{\ensuremath{v}}, \ensuremath{\operatorname{id}}(\ensuremath{v})}$.\\
           }
         }
         \lIf{\emph{receive message $\tuple{\text{weight update }\Delta, \ensuremath{\operatorname{id}}(\ensuremath{v}_{it})}$}}{
           $S_{\ensuremath{v},t} \gets S_{\ensuremath{v},t} \cup \set{\ensuremath{v}_{it}}$;
           $Z_{\ensuremath{v},i} \gets Z_{\ensuremath{v},i} + \Delta $;\\
         }
        } 
    }
  }

}
\vspace{2mm}
 \KwOut{At the end of each round $t$ each sensor has an identical local copy
  $S_{\ensuremath{v},t}$ of the selected set $S_{t}$.}

\caption{The Distributed Online Greedy Algorithm} \vspace{-5mm}

\Titleofalgo { Distributed {\algofont{EXP3}}\xspace (executing on round $t$)}
\KwIn{Parameters $\alpha, \eta, \gamma \in \ensuremath{\mathbb{R}}_{> 0}$, sensor set $V$.}
Let $\rho(x, y) := (1-\gamma)\frac{x}{y} + \frac{\gamma}{|V|}$.\\

\emph{Sensors: 
} \\
\For {\KwEach \emph{sensor $\ensuremath{v}$ in parallel}}{
  Sample $r_{\ensuremath{v}}$ uniformly at random from $[0,1]$.\\
  \If {$(r_{\ensuremath{v}} \ge 1 - \alpha \cdot \rho(w_{\ensuremath{v}}(t), Z_{\ensuremath{v}}(t))$}{
    Send $\tuple{r_{\ensuremath{v}}, w_{\ensuremath{v}}(t)}$ to the server.\\
    Receive message $\tuple{Z, w}$ from server.\\
    $Z_{\ensuremath{v}}(t+1) \gets Z$; $w_{\ensuremath{v}}(t+1) \gets w$. \\
  }\lElse{

     $Z_{\ensuremath{v}}(t+1) \gets Z_{\ensuremath{v}}(t)$; $w_{\ensuremath{v}}(t+1) \gets w_{\ensuremath{v}}(t)$.\\
  }
}
\emph{Server:}\\
 Receive messages from a set $S$ of sensors. \\
 \lIf{$S = \emptyset$}{Select nothing and wait for next round.}
 \lElse{
     \For {\KwEach \emph{sensor} $\ensuremath{v} \in S$}{
       $Y_{\ensuremath{v}} \gets \min \set{x : \prob{X \le x} \ge r_{\ensuremath{v}}}$, 
       where $X \sim \Poisson{\alpha \cdot \rho(w_{\ensuremath{v}}(t),Z(t))}$.\\



       Select $\ensuremath{v}$ with probability
$Y_{\ensuremath{v}}/\sum_{\ensuremath{v}' \in S} Y_{\ensuremath{v}'}$.\\
       Observe the payoff $\ensuremath{\pi}$ for the selected
       sensor $\ensuremath{v}^*$;  
       $w_{\ensuremath{v}^*}(t+1) \gets w_{\ensuremath{v}^*}(t) \cdot \exp
       \set{\eta \ensuremath{\pi} /  \rho(w_{\ensuremath{v}^*}(t),Z(t))}$;
       $Z(t+1) \gets Z(t) + w_{\ensuremath{v}^*}(t+1) -  w_{\ensuremath{v}^*}(t)$\;
       \lFor{ \KwEach $\ensuremath{v} \in S \setminus \ensuremath{v}^*$}{
          $w_{\ensuremath{v}}(t+1) \gets w_{\ensuremath{v}}(t)$\;
       }



       \lFor{ \KwEach $\ensuremath{v} \!\in\! S$}{
         Send $\tuple{Z(t\!+\!1), w_{\ensuremath{v}}(t\!+\!1)}$ to $\ensuremath{v}$.\\
    }
  }
}
\caption{Distributed {\algofont{EXP3}}\xspace: the PMS Protocol($\alpha$) with lazy renormalization,
  applied to {\algofont{EXP3}}\xspace}

Let $A$ be the set of sensors that activate in the current iteration of
the game, and let $\paymaxact{\ensuremath{v}} := \max \paren{\ensuremath{\pi}_{\ensuremath{v}'}
    : \ensuremath{v}' \in A \setminus \set{\ensuremath{v}}}$.

The particular reward function $\ensuremath{\psi}_{\ensuremath{v}}$ we 
choose for each sensor $\ensuremath{v}$  for each iteration of the game is 
\[
\ensuremath{\psi}_{\ensuremath{v}}(\ensuremath{\tau}) = \left\{
\begin{array}{ll}
\ensuremath{c}_{\ensuremath{v}} - \max\paren{\ensuremath{\pi}_{\ensuremath{v}} - \paymaxact{\ensuremath{v}}, 0} & \text{if
}\estimate{\ensuremath{\pi}} < \ensuremath{\tau}\\
\max\paren{\ensuremath{\pi}_{\ensuremath{v}} - \paymaxact{\ensuremath{v}}, 0} - \ensuremath{c}_{\ensuremath{v}} & \text{if
}\estimate{\ensuremath{\pi}} \ge \ensuremath{\tau}
\end{array}
\right.
\]


